using System; using System.Collections.Generic; using UnityEngine;
namespace Reflectable { [RequireComponent(typeof(Rigidbody2D),typeof(CircleCollider2D))] public sealed class ProjectileController:MonoBehaviour { public float Lifetime=20f; public int MaxBounces=80; public float Damage{get;private set;} public int Bounces{get;private set;} public event Action<ProjectileController> Expired; public event Action<ProjectileController,BlockController> BlockHit; public event Action<ProjectileController> WallBounce; Rigidbody2D body; readonly HashSet<int> contacts=new(); public void Launch(Vector2 direction,float speed,float damage){body=GetComponent<Rigidbody2D>();body.gravityScale=0;body.collisionDetectionMode=CollisionDetectionMode2D.Continuous;body.linearVelocity=direction.normalized*speed;Damage=damage;Destroy(gameObject,Lifetime);} void OnCollisionEnter2D(Collision2D c){var block=c.collider.GetComponent<BlockController>();if(block){if(contacts.Add(block.GetInstanceID()))BlockHit?.Invoke(this,block);return;}if(++Bounces>MaxBounces){Expired?.Invoke(this);Destroy(gameObject);return;}var n=c.GetContact(0).normal;body.linearVelocity=Vector2.Reflect(body.linearVelocity,n);WallBounce?.Invoke(this);} void OnCollisionExit2D(Collision2D c){var b=c.collider.GetComponent<BlockController>();if(b)contacts.Remove(b.GetInstanceID());} void OnTriggerEnter2D(Collider2D c){if(c.CompareTag("ProjectileKill")){Expired?.Invoke(this);Destroy(gameObject);}} void OnDestroy(){Expired?.Invoke(this);} } }
